MAIN='\n#include "interfaces/lua/game_api.hpp"\n#include "lua_object_handles.hpp"\n#include <cassert>\nextern "C" {\n#include <lauxlib.h>\n#include <lualib.h>\n}\nusing namespace isaac::runtime;\nstatic int GameCtor(lua_State*L){auto*p=static_cast<LuaRuntime::GameHandle*>(lua_newuserdata(L,sizeof(LuaRuntime::GameHandle)));p->reserved=0;luaL_getmetatable(L,LuaRuntime::kGameMetatable);lua_setmetatable(L,-2);return 1;}\ntemplate<class T>static void Put(std::uintptr_t o,T v){assert(o+sizeof(T)<=g_GameBytes.size());std::memcpy(g_GameBytes.data()+o,&v,sizeof(v));}\ntemplate<class T>static T Read(std::uintptr_t o){T v{};std::memcpy(&v,g_GameBytes.data()+o,sizeof(v));return v;}\nint main(int argc,char**argv){\n static_cast<void>(kScriptTemplate);static_cast<void>(&HarnessHasCollectible);static_cast<void>(&BuildPrelude);static_cast<void>(&ExpectNumber);\n if(argc!=2)return 90;const std::string scene=argv[1];CreateBlocks();g_GameBytes.resize(0x360000);FillEntities();PublishLists();PublishGame();PublishEntityList(g_RoomBytes,true);LuaRuntime::SetEngineModuleBase(g_EngineBase);LuaRuntime::SetGameBindings(g_EngineBase+kGameOwnerGlobalSlotOffset,0x2222);\n Put<std::int32_t>(0x26fa60,8);Put<std::uint32_t>(0x26fa68,0x7fffffff);Put<std::uint32_t>(0x26fa6c,0xfffffffe);Put<std::int32_t>(0x26fa70,41);Put<std::int32_t>(0x26fa74,37);Put<std::int32_t>(0x26fa78,-39);\n Put<std::int32_t>(0x24f9ac,-16);Put<float>(0x24f9bc,0.25F);Put<float>(0x24f9c0,0.75F);Put<std::int32_t>(0x26fa38,5);Put<std::int32_t>(0x2f0050,9);Put<std::int32_t>(0x2f0054,8);\n std::uint64_t bosses[2]{1,2};Put<std::uintptr_t>(0x2f0038,reinterpret_cast<std::uintptr_t>(bosses));Put<std::uintptr_t>(0x2f0040,reinterpret_cast<std::uintptr_t>(bosses)+16);\n auto*L=luaL_newstate();luaL_requiref(L,"_G",luaopen_base,1);lua_pop(L,1);luaL_requiref(L,LUA_MATHLIBNAME,luaopen_math,1);lua_pop(L,1);static_cast<void>(RegisterIsaacApi(L));luaL_newmetatable(L,LuaRuntime::kGameMetatable);lua_newtable(L);static_cast<void>(AttachGameMethods(L));lua_pushcclosure(L,GameIndex,1);lua_setfield(L,-2,"__index");lua_pop(L,1);lua_pushcfunction(L,GameCtor);lua_setglobal(L,"Game");\n const char*script=R"LUA(\ngame=Game()\nassert(select(\'#\',game:SetLastDevilRoomStage(\'4294967303\'))==0)\ngame:SetLastLevelWithDamage(-3);game:SetLastLevelWithoutHalfHp(4)\ngame:AddTreasureRoomsVisited();assert(game:GetTreasureRoomVisitCount()==9)\ngame:AddStageWithoutHeartsPicked();assert(game:GetStagesWithoutHeartsPicked()==-2147483648)\ngame:AddStageWithoutDamage();assert(game:GetStagesWithoutDamage()==-1);game:ClearStagesWithoutDamage();assert(game:GetStagesWithoutDamage()==0)\nassert(game:GetDevilRoomDeals()==41);assert(game:GetDonationModGreed()==37);assert(game:GetDonationModAngel()==-39)\ngame:ClearDonationModGreed();game:ClearDonationModAngel();assert(game:GetDonationModGreed()==0 and game:GetDonationModAngel()==0)\nassert(game:GetNumEncounteredBosses()==2)\nlocal shake=game:GetScreenShakeCountdown();assert(shake==-16 and math.type(shake)==\'float\')\nassert(game:GetDarknessModifier()==0.25 and game:GetTargetDarkness()==0.75 and game:HasHallucination())\ngame:AddPixelation(5);game:AddPixelation(12)\nassert(not pcall(function()game:SetLastDevilRoomStage({})end));assert(not pcall(function()game:SetLastLevelWithDamage(1.5)end));assert(not pcall(function()game:SetLastLevelWithoutHalfHp(false)end));assert(not pcall(function()game:AddPixelation()end))\n\nlocal REVEL={game=game};local AddPixelation=12\nREVEL.game:AddPixelation(AddPixelation)\n)LUA";\n if(luaL_dostring(L,script)){std::fprintf(stderr,"%s\\n",lua_tostring(L,-1));return 1;}\n assert(Read<std::int32_t>(0x26fa5c)==7&&Read<std::int32_t>(0x2f002c)==-3&&Read<std::int32_t>(0x2f0020)==4);\n assert(Read<std::int32_t>(0x26fa60)==9&&Read<std::uint32_t>(0x26fa68)==0x80000000&&Read<std::uint32_t>(0x26fa6c)==0);\n assert(Read<std::int32_t>(0x2f0050)==12&&Read<std::int32_t>(0x2f0054)==12);\n if(scene=="live"){\n  Put<float>(0x24f9bc,-0.5F);Put<float>(0x24f9c0,1.5F);Put<std::int32_t>(0x26fa38,0);Put<std::uintptr_t>(0x2f0040,reinterpret_cast<std::uintptr_t>(bosses));\n  if(luaL_dostring(L,"assert(game:GetDarknessModifier()==-0.5 and game:GetTargetDarkness()==1.5 and not game:HasHallucination());assert(game:GetNumEncounteredBosses()==0)"))return 2;\n }\n if(scene=="dead"){\n  WriteWord(g_OwnerSlotBytes,0,0);\n  if(luaL_dostring(L,"assert(not pcall(function()game:GetDarknessModifier()end));assert(not pcall(function()game:AddStageWithoutDamage()end))"))return 3;\n }\n lua_close(L);return 0;}\n'
class Game21Behavior(unittest.TestCase):
 def test_real_game_fields_and_effects(self):
  source=fixture.HARNESS[:fixture.HARNESS.index('int main(')]+MAIN
  source=re.sub(r'namespace GameFileReader \{\nTextReadResult[\s\S]*?\n\}\n\}', '',source,count=1)
  with tempfile.TemporaryDirectory(prefix='api300-game-')as d:
   binary=build_lua_harness(source_root=fixture.SOURCE,workdir=Path(d),harness_source=source)
   for scene in ('normal','live','dead'):
    result=subprocess.run([str(binary),scene],capture_output=True,text=True);self.assertEqual(result.returncode,0,scene+result.stdout+result.stderr)

